#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeReaderSavedService: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = ReaderSavedService

    public static func lift(_ handle: UInt64) throws -> ReaderSavedService {
        return ReaderSavedService(unsafeFromHandle: handle)
    }

    public static func lower(_ value: ReaderSavedService) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ReaderSavedService {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ReaderSavedService, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeReaderSavedService_lift(_ handle: UInt64) throws -> ReaderSavedService {
    return try FfiConverterTypeReaderSavedService.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeReaderSavedService_lower(_ value: ReaderSavedService) -> UInt64 {
    return FfiConverterTypeReaderSavedService.lower(value)
}






/**
 * One reader's Reader: an account's, or the reader's who isn't signed in.
 *
 * It's the entry point to the Reader, as `WpService` is to a site. Everything it hands out reads
 * from the cache, so it shows what it has straight away and offline, and fetches when asked to.
 *
 * Create one per reader and share it. For [`ReaderOwner::SignedOut`], pass a delegate that sends
 * no authentication: a stream that needs an account then fails with
 * [`ReaderError::NeedsAccount`] without sending anything.
 *
 * Tell it the reader's language with [`Self::set_language`], straight after creating it and again
 * whenever it changes. The delegate's `language_provider` isn't used: the Reader sends its own
 * language, and only on the requests whose answer it changes, so that what it caches is always in
 * the language its key says.
 *
 * [`WpApiCache::remove_reader_data`] deletes everything it keeps, except the saved posts' stored
 * image files: see [`ReaderSavedService::remove_offline_images`].
 */
public protocol ReaderServiceProtocol: AnyObject, Sendable {
    
    /**
     * A post as the cache has it, with its content, or `None` if the cache doesn't have it.
     * `key` is the post's [`ReaderPostRecord::key`]. Doesn't touch the network.
     */
    func cachedPost(key: ReaderSavedKey) throws  -> ReaderPostRecord?
    
    /**
     * Deletes what nothing shows any more: streams nobody has refreshed in 30 days, and posts
     * that are in no stream, aren't saved and weren't fetched in the last week. A stream's
     * refresh does this too, so it only needs calling for a reader who never refreshes.
     */
    func cleanUp() throws 
    
    /**
     * The reader's language, as last set with [`Self::set_language`].
     */
    func language()  -> WpComLanguage?
    
    /**
     * Who this Reader belongs to.
     */
    func owner()  -> ReaderOwner
    
    /**
     * The reader's saved posts. A signed-out reader's are kept on this device only: see
     * [`ReaderSavedService::for_reader`].
     */
    func saved()  -> ReaderSavedService
    
    /**
     * Sets the reader's language: pass the device's, or the app's own if it has one. `None`, the
     * default, sends no language, and WordPress.com answers in English.
     *
     * The Reader sends it where it changes the answer: a tag's posts, several tags' posts,
     * Discover, the first posts of new sites and a search are picked in it, and the menu and
     * [`Self::interests`] are translated into it. Other streams, such as a site's, are the same in
     * any language and are sent none.
     *
     * Each language's posts are cached apart: a stream got after a change is the new language's,
     * and shows none of the other's. A stream got before keeps its language: see
     * [`ReaderStreamCollection`]. The cached menu stays in the language it was fetched in until
     * [`Self::refresh_menu`] runs again.
     */
    func setLanguage(language: WpComLanguage?) 
    
    /**
     * A stream's posts, as the cache has them, in the reader's language for a stream whose posts
     * depend on it. Getting it doesn't touch the network.
     */
    func stream(stream: ReaderStream)  -> ReaderStreamCollection
    
    /**
     * Follows, for this account, the tags that were followed on this device while nobody was
     * signed in, and empties the signed-out reader's list. Call it after sign-in, on the
     * account's service.
     *
     * Every tag is a follow of this account's before anything is sent, as if the reader had
     * tapped it, so none is lost if the call stops part-way: what isn't sent waits for
     * [`Self::sync_actions`]. A tag the server refuses goes back to how this account had it, and
     * is listed in [`ReaderTagAdoptionReport::refused`]; the others are still sent. A tag the
     * account already follows stays followed.
     */
    func adoptSignedOutTags() async throws  -> ReaderTagAdoptionReport
    
    /**
     * The sites the user blocked, as the cache has them, by name.
     */
    func blockedSites() throws  -> [ReaderBlockedSite]
    
    /**
     * The users the reader blocked on this device, in the order they were blocked.
     */
    func blockedUsers() throws  -> [WpComUserId]
    
    /**
     * How many things the user turned on or off are waiting to be sent. Saves aren't among
     * them: [`ReaderSavedService::pending_count`](crate::service::reader_saved::ReaderSavedService::pending_count)
     * counts those.
     */
    func pendingActionCount() throws  -> UInt64
    
    /**
     * Fetches the sites the user blocked, so a block made on another device shows on this one. A
     * block or unblock made here that's still waiting to be sent stays as the user left it. Needs
     * an account.
     *
     * The server's list can be wrong about a site just unblocked, and stay wrong. As measured on
     * 2026-11-20:
     *
     * - The server keeps its answer for each page and page size. Page 1 and 100 a page are the
     * defaults, so `page=1&per_page=100`, `per_page=100` and no parameters share one answer;
     * another page size has its own. A cache-busting parameter doesn't change it.
     * - When reads of the list are on their way while the server takes an unblock, the server
     * can go on listing the site for that page size: 3 times in 3 tries, for at least 10
     * minutes (14 in an earlier run), until the next block or unblock, which a second, no-op
     * unblock of the site is. `read/sites/{id}`'s `is_blocked` was right throughout.
     * - A read that starts after the unblock is answered was right (6 tries), as were reads
     * during a block (no list left the site out, 3 tries) and reads of the Following stream
     * on their way during an unblock (3 tries). One live run did get a stale list with no other
     * read of the list found to overlap the unblock, so not every cause is known.
     *
     * So this doesn't read the list while a block or unblock of this service's is being sent,
     * and doesn't send one while it reads. And when the list disagrees with a block or unblock
     * the server took from this service, the site is asked about by `read/sites/{id}`, and its
     * `is_blocked` decides: what the cache has is kept when it agrees with that change, and the
     * list is taken when it doesn't (blocked or unblocked elsewhere since). A site that can't be
     * asked about, such as a deleted one (410), is taken as the list has it. A site is asked
     * about only until the list agrees with the change, and only by the service that made it: a
     * new service, such as after a restart, takes the list as it is.
     *
     * The site is asked for whole, with no `fields`, as [`Self::fetch_site`] asks: the server
     * keeps an answer for each value of `fields`, and a kept answer is what the check gets
     * around. On 2026-11-20 that request answered `is_blocked: false` for a site that wasn't
     * blocked, and 410 `site_gone` for the only site the account had blocked, a deleted one, so
     * its `is_blocked: true` for a blocked site rests on the measurements above.
     */
    func refreshBlockedSites() async throws 
    
    /**
     * Turns emails for a followed site's new comments on or off. Needs an account.
     *
     * The server ties it to the site's posts' comment subscriptions: turning it on subscribes
     * the user to them, with notifications off, and turning it off unsubscribes them, as
     * measured on a site with one post (see [`Self::set_comments_subscribed`]). Posts already in
     * the cache keep the subscription they had until they're fetched again.
     */
    func setCommentEmails(siteId: WpComSiteId, enabled: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Likes or unlikes a comment. Needs an account.
     */
    func setCommentLiked(siteId: WpComSiteId, commentId: CommentId, liked: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Turns notifications for the comments of a post the user is subscribed to on or off. Needs
     * an account, and a post of a WordPress.com or Jetpack site: a feed's post is refused with
     * [`ReaderError::FeedPost`].
     *
     * The server answers with the subscription as it now has it, and the cached post shows that
     * answer. For a post the user isn't subscribed to, turning them on still answers 200, with
     * "not subscribed": that's refused with [`ReaderError::Refused`], and the post shows as not
     * subscribed. While the site's comment emails are on, turning them on answers with them
     * off, and is refused the same way. See [`Self::set_comments_subscribed`].
     */
    func setCommentNotifications(post: ReaderPostSaveIdentity, enabled: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Subscribes the user to a post's comments, or unsubscribes them. Unsubscribing ends the
     * post's comment notifications too. Needs an account, and a post of a WordPress.com or
     * Jetpack site: a feed's post is refused with [`ReaderError::FeedPost`].
     *
     * The server answers with the subscription as it now has it, and the cached post shows that
     * answer: a new subscription's notifications are off unless the server says otherwise. An
     * answer that isn't what was asked is refused with [`ReaderError::Refused`], and the post
     * shows what the server answered rather than going back.
     *
     * A post's subscription follows the site's comment emails ([`Self::set_comment_emails`]).
     * As measured on 2026-11-20, on a site the account owns with one post: turning the site's
     * comment emails on made the post read as subscribed with notifications off, and while they
     * were on, an unsubscribe answered `success: true` and still subscribed (so it's refused
     * here). Turning them off unsubscribed the post, including a subscription made before they
     * were turned on. Turning them off when they were already off left the post's subscription
     * alone. Posting a comment on the post didn't subscribe the user to it.
     */
    func setCommentsSubscribed(post: ReaderPostSaveIdentity, subscribed: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Follows or unfollows a site or a feed. Every cached post of it, what's cached of the site,
     * and the list of subscriptions show it straight away. Needs an account.
     *
     * When it changes whether the cached site is followed, the site's subscriber count counts
     * the reader in or out with it, and goes back with it if the server refuses.
     *
     * A follow is sent by the site's or feed's address, and an unfollow by the site's ID when
     * there is one.
     */
    func setFollowed(target: ReaderFollowTarget, followed: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Sets how often a followed site's new posts are emailed. Unlike the on/off settings, this
     * one isn't kept to send later: it returns the error if it can't be sent now. Needs an
     * account. It's sent once no other change of this service's is being sent.
     */
    func setPostEmailFrequency(siteId: WpComSiteId, frequency: ReaderSubscriptionEmailFrequency) async throws 
    
    /**
     * Turns emails for a followed site's new posts on or off. Needs an account.
     */
    func setPostEmails(siteId: WpComSiteId, enabled: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Likes or unlikes a post, and counts a view of it for a like when `page_view` asks and it's
     * one that counts. The post's like count moves with it, straight away, and is set to the
     * server's once it answers. Only a post of a WordPress.com or Jetpack site can be liked: a
     * feed's post is refused with [`ReaderError::FeedPost`].
     *
     * Pass the same `page_view` as to [`Self::post_opened`]. A like counts a view under the same
     * rules as opening the post, as both WordPress apps count one: an unlike, or a like of a post
     * the cache shows liked already, counts none, and a like made offline is sent later but its
     * view isn't. See the `page_views` module.
     *
     * The like and the view are done together and reported apart: an error of one is in its own
     * part of the outcome. The call fails with [`ReaderError::NeedsAccount`] signed out, sending
     * nothing, and otherwise only when the cache can't be read.
     */
    func setPostLiked(post: ReaderPostSaveIdentity, liked: Bool, pageView: ReaderPageViewChoice) async throws  -> ReaderPostLikedOutcome
    
    /**
     * Turns notifications for a followed site's new posts on or off. Needs an account.
     */
    func setPostNotifications(siteId: WpComSiteId, enabled: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Marks a post as seen or unseen. It shows straight away. Needs an account.
     *
     * A post has a seen state when the stream that sent it gave it one, which the Following
     * stream does: [`wp_mobile_cache::db_types::reader::ReaderPostRecord::is_seen`] is `None`
     * for a post that has none, and marking such a post is refused by the server.
     *
     * When it changes the cached post's seen state, the followed site's (or an RSS post's feed's)
     * [`ReaderSubscriptionRecord::unseen_count`] goes down by one for seen, never below zero, and
     * up by one for unseen, as Android moves it, and goes back if the server refuses.
     */
    func setPostSeen(post: ReaderPostSaveIdentity, seen: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Blocks or unblocks a site. The Reader's streams leave out a blocked site's posts, straight
     * away. Needs an account.
     *
     * A block doesn't unfollow the site. While it's blocked, the server describes the site and
     * its posts as not followed, with no email or notification settings, and leaves the reader
     * out of its subscriber count, but it keeps the subscription: an unblock brings the follow
     * back with its delivery settings as they were. So a fetch made during the block stores "not
     * followed", and when the server takes an unblock, a site the cached subscriptions list is
     * shown as followed again, on the site and on its posts.
     *
     * The server answers a block or unblock with `success: false` when the site was already as
     * asked, which is taken as done. It doesn't read the list of blocked sites back: the cache
     * already has the change. The server's list can go on listing a site after an unblock it
     * took, when reads of the list were on their way meanwhile, until the next block or unblock;
     * [`Self::refresh_blocked_sites`] says how it guards against that. Unblocking the site
     * again, a no-op, clears it.
     */
    func setSiteBlocked(siteId: WpComSiteId, blocked: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Follows or unfollows a tag. `title` is the tag's name, to show with it. It shows in
     * [`Self::followed_tags`] straight away.
     *
     * Signed out, the tag is followed on this device only, and nothing is sent:
     * [`Self::adopt_signed_out_tags`] takes such tags over after sign-in.
     *
     * The server can answer 200 to a follow or unfollow it doesn't keep. As measured on
     * 2026-11-20 with one account:
     *
     * - Two of the account's tag changes sent at the same moment keep only one: 6 times in 6,
     * whether a follow and an unfollow or two follows, each answered 200 with the tag it
     * added or removed. The next change of the tags is kept.
     * - Follows sent while the account's other changes were being sent answered 200 with the
     * tag in `added_tags`, and weren't kept: beside the live trial that likes a post alone, 2
     * of 2; beside the one that marks posts seen alone, 2 of 2; beside the seven trials that
     * make a change and put it back, 13 of 14; beside every Reader trial, 7 of 19. Every read
     * then said the tag wasn't followed, and unfollowing it was refused as `not_subscribed`.
     * None was lost beside the block trial alone (4 follows) or beside trials that only read
     * (4 follows).
     * - Once, during such a run, an unfollow left the tag listed as followed by every read
     * (`read/tags` in `rest/v1.1` and `rest/v1.2`, `read/tags/{slug}/mine`, the menu) for 13
     * to 16 minutes. Seven more unfollows each answered 200 with the tag in `removed_tag`, and
     * a follow answered with nothing added, and none of them changed it; it ended on its own.
     * That wasn't seen again.
     * - Reads of the tags or the menu on their way during a follow or unfollow, or made straight
     * after one, never left the tags wrong (21 tries).
     *
     * The answer lists every tag the user then follows. When that list doesn't have a tag the
     * follow says it added, or still has the tag an unfollow says it removed, the change is
     * refused with [`ReaderError::Refused`] and the tag shows as the list has it. A tag in the
     * list that couldn't be read is taken as the added or removed one when its ID matches, and
     * leaves the follow unchecked when its ID couldn't be read either. That caught 22 of the 24
     * follows that weren't kept: the other two answers listed the tag and the server still
     * dropped it. No read says otherwise once the server has dropped a change, so nothing else
     * is checked.
     *
     * This service sends its own changes one at a time, in one lane: everything it turns on or
     * off (tags, likes, seen, follows, blocks, a comment's like, comment subscriptions and a
     * site's delivery settings), [`Self::set_post_email_frequency`], and the comments posted
     * through [`Self::comments`]. So a tag change of this service's never overlaps another of
     * its changes, and [`Self::refresh_menu`] doesn't read the menu while one is being sent.
     * Saves aren't in that lane ([`Self::saved`] sends them in its own), nor are page views,
     * which count a view rather than change the account; neither was measured beside a tag
     * follow. Nothing here holds back another device or app signed in to the account.
     */
    func setTagFollowed(slug: ReaderTagSlug, title: String?, followed: Bool) async throws  -> ReaderActionOutcome
    
    /**
     * Blocks or unblocks a user. The Reader's streams leave out a blocked user's posts, and a
     * post's comments leave out their comments and the replies under them. Nothing is deleted, so
     * an unblock shows them again.
     *
     * WordPress.com keeps no list of blocked users, so this one lives on this device only, and
     * works signed out too.
     */
    func setUserBlocked(userId: WpComUserId, blocked: Bool) throws 
    
    /**
     * Sends what the user turned on or off that the server doesn't have yet, such as a post
     * marked as seen while offline. Returns how many are still waiting. Call it at launch, when
     * the app comes to the foreground, and when the device comes back online.
     */
    func syncActions() async throws  -> UInt64
    
    /**
     * A post's comments, as the cache has them. Getting it doesn't touch the network. Only a
     * post of a WordPress.com or Jetpack site has comments the Reader can show.
     */
    func comments(siteId: WpComSiteId, postId: PostId)  -> ReaderCommentsCollection
    
    /**
     * Finds what a link opens in the Reader: a post, a site, a feed, or nothing the Reader can
     * show, which is [`ReaderLink::NotInReader`] with the reason. A post is fetched and kept in
     * the cache, and a site or feed's details are too. An error is the server refusing, such as
     * for a private site the reader can't see, or the request failing.
     *
     * - One of the Reader's own addresses, such as `https://wordpress.com/read/blogs/{site}` or
     * `https://wordpress.com/reader/feeds/{feed}/posts/{item}`, is read for the site, feed or
     * post it names, which is then fetched as [`Self::fetch_site`], [`Self::fetch_feed`] or
     * [`Self::fetch_post`] fetch it: nothing is sent to the resolver, and a public site's or a
     * feed's needs no account. One that names nothing, or names IDs the server doesn't have, is
     * [`ReaderLinkNotInReader::NothingThere`]. The module's documentation lists the shapes.
     * - One of the Reader's own pages of another stream, such as `https://wordpress.com/tag/cats`
     * or `https://wordpress.com/discover/search?q=cats`, is a [`ReaderLink::Stream`], and the
     * search page with no query a [`ReaderLink::Search`]. Nothing is sent. Signed out, the
     * address of a stream that needs an account, such as Following or Liked, is
     * [`ReaderError::NeedsAccount`].
     * - A site's home address, such as `https://example.com/`, is looked up as a WordPress.com
     * or Jetpack site, then as an address with a feed. It needs no account.
     * - Any other address is resolved to a post, which needs an account: the server only does it
     * with a token. Where the server finds no post, the address is looked up for a feed, so a
     * site's address with a path, such as `https://wordpress.com/blog/`, opens the site.
     * - Signed out, such an address is tried as a post by its slug instead, as the Android app
     * tries it: the address's host is the site, and the last part of its path the slug. A post
     * found that way is a [`ReaderLink::Post`]. A host that's no WordPress.com or Jetpack
     * site's (404 `unknown_blog`) is looked up for a feed, as it is with an account. Anything
     * else is [`ReaderError::NeedsAccount`], since the resolver might find what the slug
     * didn't: a server's refusal of the slug, such as no post with it or a private site. An
     * address with no slug has its host looked up as a site instead: a feed or nothing when no
     * site has it, and [`ReaderError::NeedsAccount`] when one does or the server refuses. A
     * request that fails, rather than being refused, is the error. See `post_slug` for what
     * was measured.
     * - The server answers an address that isn't on a WordPress.com or Jetpack site with a 404
     * `blog_not_found`, and the address is looked up for a feed. Until 2026-11-20 it answered
     * with a 500 instead: the site's domain is then looked up, and when no WordPress.com or
     * Jetpack site has it, the address is looked up for a feed. When one does, the 500 is the
     * error.
     * - A `wp.me` short link isn't resolved by the server: [`ReaderLinkNotInReader::ShortLink`].
     */
    func resolveLink(url: String) async throws  -> ReaderLink
    
    /**
     * Reports that a post was opened: marks it as seen, and counts a view of it when `page_view`
     * asks and it's one that counts. `key` is the post's key in the cache. Call it once each time
     * the reader opens the post.
     *
     * The mark is only for an account, and only for a post that has a seen state and isn't seen
     * yet. It shows straight away in every stream that has the post, and one made offline is sent
     * later. A view works signed out.
     *
     * The two are done together and reported apart: an error of one is in its own part of the
     * outcome. The call itself only fails when the cache can't be read.
     */
    func postOpened(key: ReaderSavedKey, pageView: ReaderPageViewChoice) async throws  -> ReaderPostOpenedOutcome
    
    /**
     * Fetches the sites the account is a member of. Needs an account.
     */
    func refreshMemberSites() async throws 
    
    /**
     * Tells the Reader which sites the account is a member of, for an app that already has
     * them. Without it, the Reader fetches them itself the first time a post is opened, and
     * again once they're a day old.
     */
    func setMemberSites(siteIds: [WpComSiteId]) throws 
    
    /**
     * The users who liked a comment, newest like first, a page at a time, as
     * [`Self::post_likes`]. Not cached.
     */
    func commentLikes(siteId: WpComSiteId, commentId: CommentId, params: ReaderLikesParams) async throws  -> ReaderLikesResponse
    
    /**
     * Fetches a post by its IDs, stores it in the cache, and returns it with its content.
     *
     * For a post to show from a link or a notification, and to bring a cached post up to date.
     * A public site's or feed's post needs no account.
     */
    func fetchPost(post: ReaderPostSaveIdentity) async throws  -> ReaderPostRecord
    
    /**
     * Fetches a site's post by its slug, stores it in the cache, and returns it with its content.
     * `site` is the site's ID or its domain.
     *
     * The slug finds the post's IDs, and the post is then fetched as [`Self::fetch_post`] fetches
     * it, because a post found by its slug comes without what the Reader shows of its site.
     */
    func fetchPostBySlug(site: WpComSiteIdentifier, slug: String) async throws  -> ReaderPostRecord
    
    /**
     * The users who liked a post, newest like first, a page at a time. Pass the default `params`
     * for the first page, and the previous page's `next_page_params` for the next. A public
     * site's needs no account. Not cached.
     */
    func postLikes(siteId: WpComSiteId, postId: PostId, params: ReaderLikesParams) async throws  -> ReaderLikesResponse
    
    /**
     * What the cache has of a site, or of a feed when there's no site ID to look by. Doesn't
     * touch the network.
     */
    func cachedSite(siteId: WpComSiteId?, feedId: ReaderFeedId?) throws  -> ReaderSiteRecord?
    
    /**
     * Fetches what the Reader shows of a feed besides its posts, and keeps it in the cache.
     * Needs no account.
     */
    func fetchFeed(feedId: ReaderFeedId) async throws  -> ReaderSiteRecord
    
    /**
     * Fetches what the Reader shows of a site besides its posts, such as its name, its
     * description and how many follow it, and keeps it in the cache. A public site needs no
     * account.
     */
    func fetchSite(siteId: WpComSiteId) async throws  -> ReaderSiteRecord
    
    /**
     * Fetches every site and feed the account follows, a page at a time, and replaces the cached
     * list with them. A follow or unfollow made here that's still waiting to be sent stays as
     * the reader left it. Returns how many there are. Needs an account.
     */
    func refreshSubscriptions() async throws  -> UInt64
    
    /**
     * Searches sites and feeds, best match first. `offset` is where the page starts: `None` for
     * the first, and the previous page's `next_offset` after it. Needs no account. Not cached.
     *
     * A query that looks like an address finds the feed at that address.
     *
     * The sites and feeds the reader follows are among the results, with `is_following` set on
     * their site and feed, as both WordPress apps ask. The server leaves them out unless told not
     * to: on 2026-11-20 a search for a followed site's name found it only with
     * `exclude_followed=false`.
     */
    func searchSites(query: String, offset: UInt32?) async throws  -> ReaderFeedSearchResponse
    
    /**
     * The sites and feeds the account follows, from the cache, newest follow first.
     */
    func subscriptions() throws  -> [ReaderSubscriptionRecord]
    
    /**
     * A user's public profile, by their login or their user ID. Prefer the login when it's known:
     * the API reads a number as a login first. Needs an account. Not cached.
     */
    func userProfile(user: WpComUserIdentifier) async throws  -> ReaderUserProfile
    
    /**
     * The tags the reader follows, from the cache.
     */
    func followedTags() throws  -> [ReaderMenuItem]
    
    /**
     * The tags a new reader picks from, in the reader's language: which tags they are, and their
     * names, depend on it. See [`Self::set_language`]. Works signed out. Not cached.
     */
    func interests() async throws  -> [ReaderInterest]
    
    /**
     * The Reader menu, from the cache. Empty until [`Self::refresh_menu`] has run once, apart
     * from tags followed on this device.
     */
    func menu() throws  -> ReaderCachedMenu
    
    /**
     * Fetches the Reader menu. Works signed out, where it brings the default streams and the
     * recommended tags, and leaves the tags followed on this device as they are.
     *
     * For an account, the followed tags become the server's, apart from a follow or unfollow
     * made here that's still waiting to be sent.
     *
     * The names of the Reader's own streams are in the reader's language, such as `Découvrir` for
     * Discover: see [`Self::set_language`]. The entries are the same in any language, and tags'
     * names aren't translated. The menu is cached in the language it was fetched in, so after a
     * change of language, it's the new language's once this has run again.
     *
     * It doesn't read the menu while a change of this service's, such as a tag follow, is being
     * sent, and the service doesn't send one while it reads, so a menu read before a follow or
     * unfollow isn't stored after the server has taken it. The server's followed tags can still
     * be wrong after a change it answered 200 to: [`Self::set_tag_followed`] has what was
     * measured. As measured on 2026-11-20, every read of the followed tags agreed with every
     * other each time (the menu, `read/tags` in `rest/v1.1` and `rest/v1.2`, and
     * `read/tags/{slug}/mine`), so none can be asked to check the menu.
     */
    func refreshMenu() async throws 
    
    /**
     * A tag's name and description. Works signed out. Not cached. It doesn't say whether the
     * reader follows the tag: [`Self::followed_tags`] does.
     */
    func tagInfo(slug: ReaderTagSlug) async throws  -> ReaderTag
    
}
/**
 * One reader's Reader: an account's, or the reader's who isn't signed in.
 *
 * It's the entry point to the Reader, as `WpService` is to a site. Everything it hands out reads
 * from the cache, so it shows what it has straight away and offline, and fetches when asked to.
 *
 * Create one per reader and share it. For [`ReaderOwner::SignedOut`], pass a delegate that sends
 * no authentication: a stream that needs an account then fails with
 * [`ReaderError::NeedsAccount`] without sending anything.
 *
 * Tell it the reader's language with [`Self::set_language`], straight after creating it and again
 * whenever it changes. The delegate's `language_provider` isn't used: the Reader sends its own
 * language, and only on the requests whose answer it changes, so that what it caches is always in
 * the language its key says.
 *
 * [`WpApiCache::remove_reader_data`] deletes everything it keeps, except the saved posts' stored
 * image files: see [`ReaderSavedService::remove_offline_images`].
 */
open class ReaderService: ReaderServiceProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_wp_mobile_fn_clone_readerservice(self.handle, $0) }
    }
    /**
     * Uses what the cache has for the reader. `cache` must have had its migrations run.
     * `saved_source` is the app, which is recorded with each save.
     */
public convenience init(delegate: WpApiClientDelegate, cache: WpApiCache, owner: ReaderOwner, savedSource: ReaderSavedSource)throws  {
    let handle =
