                )
            },
            pollFunc: ffi_wp_mobile_rust_future_poll_rust_buffer,
            completeFunc: ffi_wp_mobile_rust_future_complete_rust_buffer,
            freeFunc: ffi_wp_mobile_rust_future_free_rust_buffer,
            liftFunc: FfiConverterTypeReaderActionOutcome_lift,
            errorHandler: FfiConverterTypeReaderError_lift
        )
}
    
