#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeReaderService: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = ReaderService

    public static func lift(_ handle: UInt64) throws -> ReaderService {
        return ReaderService(unsafeFromHandle: handle)
    }

    public static func lower(_ value: ReaderService) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ReaderService {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ReaderService, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeReaderService_lift(_ handle: UInt64) throws -> ReaderService {
    return try FfiConverterTypeReaderService.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeReaderService_lower(_ value: ReaderService) -> UInt64 {
    return FfiConverterTypeReaderService.lower(value)
