/**
 * What the device has of the saved posts after [`ReaderSavedService::download_for_offline`].
 */
public struct ReaderOfflineReport: Equatable, Hashable {
    /**
     * Saves whose content is on the device.
     */
    public let ready: UInt64
    /**
     * Of those, the saves whose images are too.
     */
    public let withImages: UInt64
    /**
     * Saves whose content couldn't be fetched. Each says why in the saved list.
     */
    public let failed: UInt64
    /**
     * Saves whose content hasn't been fetched yet.
     */
    public let notDownloaded: UInt64
    /**
     * How much room the stored images take, in bytes.
     */
    public let imageBytes: UInt64
    /**
     * Why the download stopped before it had tried everything, such as no connection. `None`
     * when it did all it could.
     */
    public let stoppedBecause: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Saves whose content is on the device.
         */ready: UInt64, 
        /**
         * Of those, the saves whose images are too.
         */withImages: UInt64, 
        /**
         * Saves whose content couldn't be fetched. Each says why in the saved list.
         */failed: UInt64, 
        /**
         * Saves whose content hasn't been fetched yet.
         */notDownloaded: UInt64, 
        /**
         * How much room the stored images take, in bytes.
         */imageBytes: UInt64, 
        /**
         * Why the download stopped before it had tried everything, such as no connection. `None`
         * when it did all it could.
         */stoppedBecause: String? = nil) {
        self.ready = ready
        self.withImages = withImages
        self.failed = failed
        self.notDownloaded = notDownloaded
        self.imageBytes = imageBytes
        self.stoppedBecause = stoppedBecause
    }

    

    
}

