    case stale(data: FullEntityMediaWithEditContext
    )
    /**
     * Fetch failed, no cached data available
     */
    case failed(error: String
    )
    /**
     * Fetch failed, showing last known cached data
     */
    case failedWithData(error: String, data: FullEntityMediaWithEditContext
    )





}

