public 
enum ReaderSavedError: Swift.Error, Equatable, Hashable {

    
    
    case Api(WpApiError
    )
    /**
     * The post doesn't have the IDs the API needs to save it, or a key has an ID of `0` or an empty
     * URL.
     */
    case PostCannotBeSaved
    /**
     * The account has reached its save cap. A tap's save is undone. Saves without a tap waiting on
     * them, such as an import's or one made offline, stay saved, and are sent once there's room:
     * [`ReaderSavedService::sync`] returns this while any are waiting, and
     * [`ReaderSavedService::saves_waiting_for_room`] says how many.
     */
    case TooManySaves
    /**
     * An import batch got back a different number of results than the keys it sent, so no result
     * can be matched to its key. The server may have saved any of them, so they wait for a refresh.
     */
    case UnexpectedImportResults(sent: UInt64, received: UInt64
    )
    /**
     * An import batch got back results that can't all be matched to the keys it sent, such as
     * two for the same key. The server may have saved any of them, so they wait for a refresh.
     */
    case UnmatchedImportResults
    /**
     * A saved post's image couldn't be written to, or deleted from, the directory given to
     * [`ReaderSavedService::set_offline_image_store`].
     */
    case OfflineFiles(reason: String
    )
    /**
     * The server couldn't be reached to fetch a saved post's content.
     */
    case OfflineUnreachable(reason: String
    )
    case Database(SqliteDbError
    )

    

    

    
}

